// One text block for the model, plus the exact title list the
// verification step downstream will check its citations against.
const topics = $input.first().json.topic_list?.topics ?? [];
const recent = topics.filter(t => !t.pinned);
const titles = recent.map(t => t.title);
const digest = recent
  .map(t => `- ${t.title} (${t.reply_count} replies, ${t.views} views)`)
  .join('\n');
return [{ json: { titles, digest, count: recent.length } }];

// Drop any theme whose evidence was not actually in the input.
// The model is asked to quote real titles; this is what checks that it did.
// A fabricated citation is the failure mode worth designing against - it reads
// as research and is fiction.
const titles = new Set($('Collect this week\'s questions').first().json.titles);
const raw = $input.first().json.text ?? $input.first().json.output ?? '';

let parsed;
try {
  parsed = JSON.parse(String(raw).replace(/^```json\s*|\s*```$/g, '').trim());
} catch {
  return [{ json: { gaps: [], dropped: [], parse_failed: true } }];
}

const gaps = [];
const dropped = [];

for (const theme of parsed.themes ?? []) {
  const real = (theme.evidence_titles ?? []).filter(t => titles.has(t));
  if (!theme.is_docs_gap) continue;
  if (real.length < 2) {
    dropped.push({ theme: theme.theme, reason: 'fewer than two verifiable titles' });
    continue;
  }
  gaps.push({ ...theme, evidence_titles: real });
}

return [{ json: { gaps, dropped, has_gaps: gaps.length > 0 } }];
